const KEY='em-dia-v1';
const $=s=>document.querySelector(s);
const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const date=s=>s.split('-').reverse().join('/');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const total=l=>l.principal+Math.round(l.principal*l.interest/100);
const paid=l=>l.payments.reduce((s,p)=>s+p.amount,0);
const balance=l=>total(l)-paid(l);
const status=l=>balance(l)===0?'paid':l.due<today()?'late':'open';
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(new Date(s).getTime())&&new Date(s).toISOString().slice(0,10)===s;
function validate(data){if(!Array.isArray(data)||data.length>10000)throw Error('Formato inválido.');const ids=new Set();for(const l of data){if(!l||typeof l.id!=='string'||ids.has(l.id)||typeof l.name!=='string'||!l.name.trim()||l.name.length>100||!Number.isSafeInteger(l.principal)||l.principal<=0||l.principal>1e10||!Number.isFinite(l.interest)||l.interest<0||l.interest>1000||!validDate(l.start)||!validDate(l.due)||l.due<l.start||typeof l.phone!=='string'||typeof l.notes!=='string'||!Array.isArray(l.payments))throw Error('Empréstimo inválido no arquivo.');ids.add(l.id);for(const p of l.payments)if(!p||!Number.isSafeInteger(p.amount)||p.amount<=0||!validDate(p.date)||p.date<l.start)throw Error('Pagamento inválido no arquivo.');if(paid(l)>total(l))throw Error('Pagamento maior que a dívida.');}return data;}
let loans=[],filter='all',selected=null,storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw)loans=validate(JSON.parse(raw));}catch(e){storageOK=false;setTimeout(()=>alert('Não foi possível carregar os dados salvos. Eles não serão sobrescritos. Exporte o backup ou importe um arquivo válido para recuperar.'),100);}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(next,restoring=false){if(!storageOK&&!restoring){alert('Recupere os dados por meio de um backup antes de salvar.');return false;}try{validate(next);localStorage.setItem(KEY,JSON.stringify(next));loans=next;storageOK=true;render();return true;}catch(e){alert('Não foi possível salvar: '+e.message);return false;}}
function render(){const sum=fn=>loans.reduce((s,l)=>s+fn(l),0);$('#lent').textContent=money(sum(l=>l.principal));$('#received').textContent=money(sum(paid));$('#balance').textContent=money(sum(balance));const late=loans.filter(l=>status(l)==='late');$('#late').textContent=money(late.reduce((s,l)=>s+balance(l),0));$('#late-count').textContent=late.length?`${late.length} empréstimo(s) com saldo vencido`:'Nenhum empréstimo atrasado';$('#count').textContent=loans.length;$('#footer-count').textContent=`${loans.length} empréstimo(s) cadastrado(s)`;const q=$('#search').value.toLocaleLowerCase('pt-BR');const visible=loans.filter(l=>(filter==='all'||(filter==='open'?balance(l)>0:status(l)===filter))&&l.name.toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>a.due.localeCompare(b.due));$('#rows').innerHTML=visible.map(l=>`<tr><td><div class="person"><span class="avatar">${esc(l.name.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.phone||'Sem telefone')}</small></div></div></td><td>${money(l.principal)}</td><td><strong>${money(balance(l))}</strong></td><td>${date(l.due)}</td><td><span class="badge ${status(l)}">${{open:'Em aberto',late:'Atrasado',paid:'Quitado'}[status(l)]}</span></td><td><button data-detail="${esc(l.id)}">Ver detalhes →</button></td></tr>`).join('');$('#empty').hidden=visible.length>0;$('#empty h3').textContent=loans.length?'Nenhum resultado encontrado':'Sua carteira começa aqui';$('#empty p').innerHTML=loans.length?'Tente outro nome ou altere o filtro.':'Cadastre seu primeiro empréstimo e acompanhe<br>cada pagamento em um só lugar.';$('#first').hidden=loans.length>0;}
function openNew(){$('#loan-form').reset();$('#loan-form').elements.start.value=today();$('#loan-form').elements.due.min=today();$('#estimate').textContent=money(0);$('#loan-dialog').showModal();}
$('#new').onclick=openNew;$('#first').onclick=openNew;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#loan-form').addEventListener('input',()=>{const f=$('#loan-form').elements;const principal=Math.round(Number(f.principal.value)*100);$('#estimate').textContent=money(principal+Math.round(principal*Number(f.interest.value)/100));f.due.min=f.start.value;});
$('#loan-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;const name=f.name.value.trim();if(!name){f.name.focus();return;}if(f.start.value>today()){alert('A data do empréstimo não pode estar no futuro.');return;}const next={id:crypto.randomUUID(),name,phone:f.phone.value.trim(),principal:Math.round(Number(f.principal.value)*100),interest:Number(f.interest.value),start:f.start.value,due:f.due.value,notes:f.notes.value.trim(),payments:[]};if(save([...loans,next])){$('#loan-dialog').close();toast('Empréstimo cadastrado.');}};
function showDetail(id,open=true){selected=id;const l=loans.find(x=>x.id===id);if(!l)return;$('#detail-name').textContent=l.name;$('#detail-info').innerHTML=`<div class="info">Emprestado em ${date(l.start)} · Vence em ${date(l.due)}<br>Valor original: ${money(l.principal)} · Juros totais: ${l.interest}%<br>Total combinado: ${money(total(l))}<br><strong>Saldo a receber: ${money(balance(l))}</strong>${l.phone?`<br>Telefone: ${esc(l.phone)}`:''}${l.notes?`<p>${esc(l.notes)}</p>`:''}</div>`;$('#history').innerHTML=l.payments.length?l.payments.map(p=>`<div class="history-row"><span>${date(p.date)}</span><strong>${money(p.amount)}</strong></div>`).join(''):'<p class="hint">Nenhum pagamento registrado.</p>';const f=$('#payment-form');f.hidden=balance(l)===0;f.reset();f.elements.amount.max=(balance(l)/100).toFixed(2);f.elements.date.value=today();f.elements.date.min=l.start;f.elements.date.max=today();if(open)$('#detail-dialog').showModal();}
$('#rows').onclick=e=>{const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail);};
$('#payment-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements,l=loans.find(x=>x.id===selected),amount=Math.round(Number(f.amount.value)*100);if(!l||amount<=0||amount>balance(l)||f.date.value>today()||f.date.value<l.start){alert('Confira o valor e a data do pagamento.');return;}const next=loans.map(x=>x.id===selected?{...x,payments:[...x.payments,{amount,date:f.date.value}]}:x);if(save(next)){showDetail(selected,false);toast('Pagamento registrado.');}};
$('#delete').onclick=()=>{const l=loans.find(x=>x.id===selected);if(l&&confirm(`Excluir o empréstimo de ${l.name} e todo o seu histórico de pagamentos? Esta ação não pode ser desfeita.`)&&save(loans.filter(x=>x.id!==selected))){$('#detail-dialog').close();toast('Empréstimo excluído.');}};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();});$('#search').oninput=render;
$('#export').onclick=()=>{const raw=storageOK?JSON.stringify({version:1,exportedAt:new Date().toISOString(),loans},null,2):localStorage.getItem(KEY);const url=URL.createObjectURL(new Blob([raw||''],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`em-dia-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Arquivo muito grande.');const data=JSON.parse(await file.text());if(data.version!==1)throw Error('Versão de backup não reconhecida.');validate(data.loans);if(confirm(`Importar ${data.loans.length} empréstimo(s)? Os registros atuais serão substituídos. Exporte um backup antes, caso queira preservá-los.`)&&save(data.loans,true))toast('Backup importado.');}catch(err){alert('Não foi possível importar: '+err.message);}finally{e.target.value='';}};
$('#today').textContent=new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});render();
